	targetLen := len(targetNetloc)

	if targetLen > domainLen+1 &&
		targetNetloc[targetLen-domainLen-1] == '.' &&
		strings.HasSuffix(targetNetloc, domain) {
		return target
	}

	return fmt.Sprintf("https://%s", domain)
}

