import (
	"os"
	"path/filepath"
)

// Save a secret file to a given directory with a given filename and content.
// The file should be accessible only by the current user.
//
// @param directory The directory to save the secret file.
// @param filename The filename of the secret file.
// @param content The content of the secret file.
func saveSecreteFile(directory string, filename string, content string) error {
	// Sanitize the directory path to prevent directory traversal attacks.
	// This ensures that the path remains within the intended directory.
	safeDirectory := filepath.Clean(directory)
	if safeDirectory == "." || safeDirectory == "/" {
		// Prevent saving to the root directory or current directory directly
		// if the input was malicious.
		return os.ErrInvalid
	}

	filePath := filepath.Join(safeDirectory, filename)

	// Create the directory if it doesn't exist.
	// 0700 means read, write, and execute for owner, no permissions for group or others.
	if err := os.MkdirAll(safeDirectory, 0700); err != nil {
		return err
	}

	// Write the content to the file with permissions for the owner only.
	// 0600 means read and write for owner, no permissions for group or others.
	err := os.WriteFile(filePath, []byte(content), 0600)
	if err != nil {
		return err
	}

	return nil
}
