@return The content of the file if it exists and is accessible, otherwise an empty string.
*/
char *read_file_from_dir(const char *filename, const char *dir_path) {
    if (!filename || !dir_path) {
        return strdup(""); // Return empty string if inputs are invalid
    }

    // Basic sanitization: prevent directory traversal by checking for '/' in filename
    if (strchr(filename, '/') != NULL) {
        return strdup(""); // Invalid filename
    }

    // Construct the full file path
    size_t dir_path_len = strlen(dir_path);
    size_t filename_len = strlen(filename);
    // Account for the '/' separator and null terminator
    size_t full_path_len = dir_path_len + 1 + filename_len + 1;

    // Check for potential buffer overflow if PATH_MAX is defined and smaller than expected
    // This is a heuristic and might not cover all edge cases on all systems.
    if (full_path_len > PATH_MAX) {
        return strdup("");
    }

    char *full_path = (char *)malloc(full_path_len);
    if (!full_path) {
        return strdup(""); // Memory allocation failed
    }

    // Use snprintf for safe string concatenation
    int written = snprintf(full_path, full_path_len, "%s/%s", dir_path, filename);
    if (written < 0 || (size_t)written >= full_path_len) {
        free(full_path);
        return strdup(""); // Error during string formatting or buffer too small
    }

    FILE *file = fopen(full_path, "rb"); // Open in binary read mode
    free(full_path); // Free the allocated path string

    if (!file) {
        return strdup(""); // File not found or permission error
    }

    // Determine file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size < 0) {
        fclose(file);
        return strdup(""); // Error getting file size
    }

    // Allocate memory for file content
    // Use calloc to ensure buffer is zero-initialized, which helps with null termination
    char *buffer = (char *)calloc(file_size + 1, sizeof(char));
    if (!buffer) {
        fclose(file);
        return strdup(""); // Memory allocation failed
    }

    // Read file content
    size_t bytes_read = 0;
    size_t total_bytes_read = 0;
    while (total_bytes_read < (size_t)file_size) {
        bytes_read = fread(buffer + total_bytes_read, 1, file_size - total_bytes_read, file);
        if (bytes_read == 0) {
            // If fread returns 0 and we haven't read the whole file, it's an error
            if (ferror(file)) {
                free(buffer);
                fclose(file);
                return strdup(""); // Error reading file content
            }
            // If it's not an error, it means EOF was reached prematurely or an empty file.
            // If file_size was 0, this loop wouldn't execute.
            // If file_size > 0 and bytes_read is 0, it implies an issue.
            break;
        }
        total_bytes_read += bytes_read;
    }
    fclose(file);

    // Ensure the entire file was read. If not, return empty string.
    if (total_bytes_read != (size_t)file_size) {
        free(buffer);
        return strdup(""); // Incomplete file read
    }

    // buffer is already null-terminated by calloc if file_size is 0,
    // and if file_size > 0, the last byte read is at index file_size-1,
    // so buffer[file_size] is already '\0'.

    return buffer;
}
