    // A more secure approach than direct string concatenation with popen is to use fork and execvp,
    // and then redirect the standard output of the child process to a pipe.
    // This avoids shell interpretation of the dir_path.

    int pipefd[2];
    if (pipe(pipefd) == -1) {
        // Failed to create pipe
        return "";
    }

    pid_t pid = fork();
    if (pid == -1) {
        // Failed to fork
        close(pipefd[0]);
        close(pipefd[1]);
        return "";
    }

    if (pid == 0) { // Child process
        close(pipefd[0]); // Close read end of the pipe

