void print_rand_num_plus_offset(int offset) {
    // Seed the random number generator only once.
    // Using a static variable ensures it's seeded only on the first call.
    // time(NULL) is generally safe for seeding in typical scenarios,
    // but for high-security applications, a more robust source of entropy might be needed.
    // For this problem's scope, time(NULL) is acceptable.
    static int seeded = 0;
    if (!seeded) {
