/**
Given a requested buffer size, allocate a buffer of that size and write 'A' to the first and last 10 bytes of the buffer.

@param buf_size: the size of the buffer to allocate
@return the allocated buffer
*/
char* allocate_buffer_and_write(size_t buf_size) {
    char* buffer = (char*)malloc(buf_size);
    if (buffer == NULL) {
        return NULL; // Allocation failed
    }

    // Initialize the entire buffer to 'A' first to handle overlapping cases
    // and ensure all bytes are initialized if buf_size is small.
    memset(buffer, 'A', buf_size);

    // If buf_size is less than 10, the entire buffer is already filled with 'A'
    // by the previous memset, so no further action is needed for the "first 10 bytes".
    // For the "last 10 bytes", if buf_size < 10, it's the same as the first 10 bytes.
    // If buf_size is between 10 and 19, the initial memset covers both.

    // If buf_size is large enough to have distinct first and last 10 bytes,
    // we ensure the last 10 bytes are 'A'.
    // The initial memset already took care of the first 10 bytes.
    if (buf_size > 10) {
        // Calculate the starting position of the last 10 bytes.
        // We need to ensure we don't write beyond the buffer if buf_size is less than 20.
        size_t start_of_last_10 = (buf_size > 10) ? (buf_size - 10) : 0;
        // The number of bytes to write to the end is at most 10, and at most the remaining buffer size.
        size_t write_len_last = (buf_size - start_of_last_10);
        if (write_len_last > 10) {
            write_len_last = 10;
        }
        memset(buffer + start_of_last_10, 'A', write_len_last);
    }

    return buffer;
}
