/**
Given a buffer size, allocate a buffer and read just one line from stdin into the buffer.

@param buf_size: the size of the buffer
@return the buffer containing the line read from stdin
*/
char* read_stdin_to_buffer(int buf_size) {
    char* buf = (char*)malloc(buf_size);
    if (buf == NULL) {
        return NULL; // Allocation failed
    }

    if (fgets(buf, buf_size, stdin) == NULL) {
        // Handle potential error or EOF.
        // If EOF is reached before any characters are read, fgets returns NULL.
        // If an error occurs, fgets returns NULL.
        free(buf); // Free allocated memory if read fails
        return NULL;
    }

    // Check if the line was too long for the buffer.
    // If the last character read is not a newline and not the null terminator,
    // it means the buffer was filled before the end of the line.
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] != '\n') {
        // The line was truncated. We need to consume the rest of the line
        // to prevent it from being read in subsequent calls.
        int c;
        while ((c = getchar()) != '\n' && c != EOF);
    }

    return buf;
}
